bool FR1Readback::RunTest(const FString&){using namespace R1Editor;if(!Own())return false;bool Good=true;auto* A=Rig(GEditor->GetEditorWorldContext().World());Good&=A&&A->Batch.OwnedActors.IsEmpty()&&A->CommittedLoops.Edges.IsEmpty()&&!A->bAutoGenerate;for(int32 F=1;F<=3;++F){const FString N=FString::Printf(TEXT("DA_R1_TestFloor%d"),F);auto* P=LoadObject<URogueliteFloorProfile>(nullptr,*(TEXT("/Game/Roguelite/Tests/P03R1/Profiles/")+N+TEXT(".")+N));Good&=P&&P->Rules.ReliabilityPolicyVersion==2&&P->Rules.OptionalTreeReservePercent==25&&Profile(F)->Rules.ReliabilityPolicyVersion==1;if(P)Export(FString::Printf(TEXT("saved-R1-profile%d.txt"),F),P->Rules);}return TestTrue(TEXT("New policy persisted; source G1 profiles and empty Editor layout preserved"),Good);}
